class Base {
public:
    // Non-virtual: Failure point for array deletion
    ~Base() {}
};

class Derived : public Base {
    int* data = new int[1]; // Resource needing cleanup
public:
    ~Derived() { delete[] data; }
};

// 1. Array allocation (stores total size/N):
Base* p = new Derived[3];

// 2. Array Deletion via Base*:
// Compiler uses static type (Base) for destructor (~Base()).
// Compiler uses sizeof(Base) for memory step iteration.
// Fails to call Derived::~Derived() for each element.
// Result: Resource leak/Undefined Behavior/Memory corruption.
delete[] p;

// Fix: Add 'virtual' to Base::~Base() for single element deletion.
// However, array deletion via base pointer is STILL unsafe
// unless the compiler uses specific runtime VLA mechanisms.
